#!/bin/bash
# Waits for the corrected-model campaign, re-probes 0-rx VNFs, then starts the 3h long run.
cd /home/CoreRouter
until grep -q "^exit=" /home/CoreRouter/results/hil/e2e_20261121T165951Z/campaign_corrected_model/console.log; do sleep 30; done
venv/bin/python /home/CoreRouter/results/hil/e2e_tools/reprobe_zero_rx.py /home/CoreRouter/results/hil/e2e_20261121T165951Z/campaign_corrected_model /home/CoreRouter/results/hil/e2e_20261121T165951Z/supplemental_probes/corrected_model_after_vxlan_fix > /home/CoreRouter/results/hil/e2e_20261121T165951Z/supplemental_probes/reprobe_corrected.log 2>&1
mkdir -p /home/CoreRouter/results/hil/e2e_20261121T165951Z/long_3h_corrected_model/admission /home/CoreRouter/results/hil/e2e_20261121T165951Z/long_3h_corrected_model/dataplane
cp /home/CoreRouter/results/hil/e2e_20261121T165951Z/campaign_corrected_model/MODEL.json /home/CoreRouter/results/hil/e2e_20261121T165951Z/long_3h_corrected_model/MODEL.json; sed -i "s/\"started_utc\":\"[^\"]*\"/\"started_utc\":\"$(date -u +%FT%TZ)\"/" /home/CoreRouter/results/hil/e2e_20261121T165951Z/long_3h_corrected_model/MODEL.json
tmux new-session -d -s corerouter-hil-long -n admission "venv/bin/python -m src.analytics.benchmark.benchmark_testbed.run_all_scenarios --scenario normal_load --duration-hours 3 --request-interval-s 3.5 --seed 246 --no-reset --no-baselines --output-dir /home/CoreRouter/results/hil/e2e_20261121T165951Z/long_3h_corrected_model/admission 2>&1 | tee /home/CoreRouter/results/hil/e2e_20261121T165951Z/long_3h_corrected_model/admission/run.log; echo EXIT=\${PIPESTATUS[0]} >> /home/CoreRouter/results/hil/e2e_20261121T165951Z/long_3h_corrected_model/admission/run.log; sleep infinity"
tmux new-window -t corerouter-hil-long -n readiness "venv/bin/python results/rev1/e6_12h_control_plane/monitor_kubernetes.py --output /home/CoreRouter/results/hil/e2e_20261121T165951Z/long_3h_corrected_model/kubernetes_readiness.csv --interval-s 60 --duration-hours 3 2>&1 | tee /home/CoreRouter/results/hil/e2e_20261121T165951Z/long_3h_corrected_model/readiness.log; sleep infinity"
tmux new-window -t corerouter-hil-long -n dataplane "venv/bin/python /home/CoreRouter/results/hil/e2e_tools/dataplane_stability_loop.py --campaign /home/CoreRouter/results/hil/e2e_20261121T165951Z/campaign_corrected_model /home/CoreRouter/results/hil/e2e_20261121T165951Z/campaign /home/CoreRouter/results/hil/e2e_20261121T165951Z/expand --out /home/CoreRouter/results/hil/e2e_20261121T165951Z/long_3h_corrected_model/dataplane --hours 3 --interval-s 120 -n 20 2>&1 | tee /home/CoreRouter/results/hil/e2e_20261121T165951Z/long_3h_corrected_model/dataplane.log; sleep infinity"
echo "longrun_started=$(date -u +%FT%TZ)" > /home/CoreRouter/results/hil/e2e_20261121T165951Z/long_3h_corrected_model/STARTED
